<?php foreach ([['','Web pública',$profile],['admin_','Administración',$adminProfile]] as [$prefix,$label,$p]): ?><section class="nx-stack"><h3><?= $e($label) ?></h3><label>Fuente<select name="<?= $prefix ?>font"><?php foreach ($fonts as $key=>$label): ?><option value="<?= $key ?>" <?= $p['font']===$key?'selected':'' ?>><?= $e($label) ?></option><?php endforeach ?></select></label><label>Tamaño de texto<input type="number" name="<?= $prefix ?>size" min="12" max="28" value="<?= $e($p['size']) ?>" required></label><label>Tamaño de títulos<input type="number" name="<?= $prefix ?>heading" min="24" max="80" value="<?= $e($p['heading']) ?>" required></label><label>Idioma<select name="<?= $prefix==='admin_'?'backend_language':'site_language' ?>"><?php foreach (['es'=>'Español','en'=>'English','pt'=>'Português'] as $code=>$label): ?><option value="<?= $code ?>" <?= \App\Core\Settings::get($prefix==='admin_'?'backend_language':'site_language','es')===$code?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></label></section><?php endforeach ?></div><p class="nx-note">Fuentes del sistema con alternativas seguras; no se envían datos a servicios de fuentes externos. Los textos de tus páginas se traducen desde su editor, no automáticamente.</p><button class="nx-btn primary">Guardar preferencias</button></div></form>
