<section class="nx-panel" style="margin-top:24px"><div class="nx-panel-head"><h2>Traducciones de páginas</h2></div><div class="nx-panel-body nx-stack"><?php foreach ($pages as $page): ?><details><summary><?= $e($page['title']) ?></summary><?php $translations=json_decode($page['translations_json']??'{}',true)?:[]; foreach (['es'=>'Español','en'=>'English','pt'=>'Português'] as $language=>$label): ?><form method="post" class="nx-form-field nx-stack"><input type="hidden" name="csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="action" value="translation"><input type="hidden" name="page_id" value="<?= $page['id'] ?>"><input type="hidden" name="language" value="<?= $language ?>"><strong><?= $label ?></strong><label>Título traducido<input name="translated_title" maxlength="255" value="<?= $e($translations[$language]['title']??'') ?>"></label><label>Contenido traducido<textarea name="content" rows="8" maxlength="1048576"><?= $e($translations[$language]['content']??'') ?></textarea></label><p class="nx-note">Un campo vacío conserva el texto original para ese idioma.</p><button class="nx-btn">Guardar traducción</button></form><?php endforeach ?></details><?php endforeach ?></div></section>
